import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# CUDA / C++ source
cpp_source = r'''
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define THREADS_PER_BLOCK 256

__global__ void swish_kernel(const half* __restrict__ input,
                             half* __restrict__ output,
                             int64_t N) {
    int64_t idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= N) return;

    half hx = input[idx];
    float x = __half2float(hx);
    float sig = 1.0f / (1.0f + expf(-x));
    float y = x * sig;
    output[idx] = __float2half(y);
}

torch::Tensor swish_cuda(torch::Tensor input) {
    TORCH_CHECK(input.is_cuda(), "input must be a CUDA tensor");
    TORCH_CHECK(input.dtype() == torch::kHalf, "input must be float16");
    auto output = torch::empty_like(input);
    int64_t N = input.numel();

    const int threads = THREADS_PER_BLOCK;
    const int blocks = static_cast<int>((N + threads - 1) / threads);

    swish_kernel<<<blocks, threads>>>(
        reinterpret_cast<const half*>(input.data_ptr()),
        reinterpret_cast<half*>(output.data_ptr()),
        N);

    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        throw std::runtime_error(cudaGetErrorString(err));
    }
    return output;
}

PYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {
    m.def("swish_cuda", &swish_cuda, "Swish activation (CUDA)");
}
'''

